EXEC('CREATE SCHEMA engagement');
CREATE TABLE engagement.products (id uniqueidentifier PRIMARY KEY,name nvarchar(200) NOT NULL,code nvarchar(32) COLLATE Latin1_General_100_BIN2 NOT NULL UNIQUE,category nvarchar(100) NOT NULL,unit_price decimal(16,4) NOT NULL,currency nvarchar(3) NOT NULL,active bit NOT NULL,search_name nvarchar(600) COLLATE Latin1_General_100_BIN2 NOT NULL,version nvarchar(32) NOT NULL,modified_at datetime2(6) NOT NULL,modified_by nvarchar(256) NOT NULL);
CREATE TABLE engagement.opportunities (id uniqueidentifier PRIMARY KEY,name nvarchar(200) NOT NULL,customer_id uniqueidentifier NOT NULL,customer_name nvarchar(200) NOT NULL,stage nvarchar(100) NOT NULL,amount decimal(14,2) NOT NULL,currency nvarchar(3) NOT NULL,expected_close date NOT NULL,owner nvarchar(100) NOT NULL,notes nvarchar(2000) NOT NULL,search_name nvarchar(600) COLLATE Latin1_General_100_BIN2 NOT NULL,version nvarchar(32) NOT NULL,modified_at datetime2(6) NOT NULL,modified_by nvarchar(256) NOT NULL);
CREATE TABLE engagement.activities (id uniqueidentifier PRIMARY KEY,name nvarchar(200) NOT NULL,customer_id uniqueidentifier NOT NULL,customer_name nvarchar(200) NOT NULL,due_date date NOT NULL,kind nvarchar(100) NOT NULL,status nvarchar(100) NOT NULL,owner nvarchar(100) NOT NULL,notes nvarchar(2000) NOT NULL,search_name nvarchar(600) COLLATE Latin1_General_100_BIN2 NOT NULL,version nvarchar(32) NOT NULL,modified_at datetime2(6) NOT NULL,modified_by nvarchar(256) NOT NULL);
CREATE INDEX opportunity_customer ON engagement.opportunities(customer_id);
CREATE INDEX activity_customer ON engagement.activities(customer_id);
